// cppprep `verify-no-consumer:`: no selected check consumes the canonical analysis database.
const CPPPREP_NO_CONSUMER: &str = "decisions.md \"legacy `verify`의 소비자 없는 분석 DB 준비 생략\" \
    (approved 2026-11-11): native runs no canonical CMake preparation when no selected check \
    consumes its database, so the suite `analysis_context.compilation` names no database, digest, \
    origin, generator, unity setting or unit, and none of frozen's configure or generation \
    diagnostics (`cmake-configure-failed`, `cmake-cache-missing`, `cmake-generation-failed`); a \
    project's own database (`cmake-own-database`) is reported alike. The processes and files are \
    compared by legacy_engine_extras.rs::legacy_cpp_preparation_without_a_database_consumer_runs_and_writes_nothing";

// cppprep: the prepared database lives in the native shadow.
const CPPPREP_SHADOW: &str = "decisions.md \"native C++ shadow build 위치\": the canonical CMake/qmake \
    database is prepared under `.ici/rust-v1/build/legacy-<16 hex>/release/`, so its path and \
    digest, each unit's directory/output/configuration digest, the shadow paths qmake writes into \
    a unit (QT_TESTCASE_BUILDDIR, the shadow include directory, project paths qmake spells \
    absolutely from the deeper shadow and that are reported project-relative) and the \
    `qmake-capture-incomplete` row located at the database (its path and fingerprint) differ; \
    the deep BuildEngine reuses that release preparation, so its `cmake configure` record carries \
    the shadow `-B` path and the database's `-DCMAKE_UNITY_BUILD=OFF` (one argument more) where \
    frozen reconfigured `build/ici-cmake-build` without it (that record alone, checked exactly by \
    legacy_engine_extras.rs::legacy_session_configure); a source the build generates lives in that \
    shadow, the units sort by a configuration digest over those paths, and compile_db findings by \
    a fingerprint over them, so their positional comparison differs (each case equals frozen once \
    the shadow is spelled `build/ici-cmake-build`, findings and units unordered)";

